def transform(grid):
    bg_counts = {}
    for row in grid:
        for cell in row:
            bg_counts[cell] = bg_counts.get(cell, 0) + 1
    bg = max(bg_counts, key=bg_counts.get)

    structure_pixels = set()
    H = len(grid)
    W = len(grid[0])
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg:
                structure_pixels.add((r, c))

    # Find bounding box
    min_r = min(r for r, c in structure_pixels)
    max_r = max(r for r, c in structure_pixels)
    min_c = min(c for r, c in structure_pixels)
    max_c = max(c for r, c in structure_pixels)

    new_grid = [row[:] for row in grid]

    # Find spanning rows (structure at both leftmost and rightmost)
    # Find spanning cols (structure at both topmost and bottommost)
    for r in range(H):
        row_struct_cols = sorted(c for c in range(W) if (r, c) in structure_pixels)
        if len(row_struct_cols) >= 2:
            # Check if spanning from min to max
            for c in range(min_c, max_c):
                if (r, c) not in structure_pixels:
                    new_grid[r][c] = 2

    for c in range(W):
        col_struct_rows = sorted(r for r in range(H) if (r, c) in structure_pixels)
        if len(col_struct_rows) >= 2:
            # Check if spanning from min to max
            for r in range(min_r, max_r):
                if (r, c) not in structure_pixels:
                    new_grid[r][c] = 2

    return new_grid
